// template for block
path block = unitsquare;
pair block_center = (0.5,0.5);

/* Resting block */
transform rest = shift(-5, -0.9) * scale(block_size); // transformation for resting block
filldraw(rest * block, ll_grey, light_grey+p); // draw block
